const { app, BrowserWindow, ipcMain, protocol } = require('electron');
const path = require('node:path');
const fs = require('node:fs');
const { pathToFileURL } = require('node:url');

const [snapshotModule, registryModule, resourceModule, packageDir, profile, sdkPath, themePath, syntaxModule] = process.argv.slice(2);
app.setPath('userData', profile);
app.commandLine.appendSwitch('disable-gpu');
protocol.registerSchemesAsPrivileged([{ scheme: 'muster-app', privileges: { standard: true, secure: true, supportFetchAPI: true, stream: true, corsEnabled: true } }]);
(async () => {
  const { captureExtensionPackage, validateExtensionPackage } = await import(pathToFileURL(snapshotModule).href);
  const { ExtensionInstanceRegistry } = await import(pathToFileURL(registryModule).href);
  const { extensionPanelResource } = await import(pathToFileURL(resourceModule).href);
  const snapshot = captureExtensionPackage(packageDir), manifest = validateExtensionPackage(snapshot, 'demo');
  const { checkExtensionPackageSyntax } = await import(pathToFileURL(syntaxModule).href);
  await checkExtensionPackageSyntax(snapshot);
  const context = { workspaceId: 'a', extensionId: 'demo', sourceRootId: 'a1', controlRoot: packageDir, sourceRoot: packageDir, extensionDirectory: packageDir, dataDirectory: profile, fingerprint: snapshot.fingerprint, manifest, snapshot, assertCurrent() {} };
  const registry = new ExtensionInstanceRegistry(), identity = registry.open(context, 'main');
  const assets = { sdk: fs.readFileSync(sdkPath, 'utf8'), theme: fs.readFileSync(themePath, 'utf8') };
  await app.whenReady();
  protocol.handle('muster-app', request => extensionPanelResource(registry, identity, request, assets));
  const window = new BrowserWindow({ show: false, webPreferences: { sandbox: true, contextIsolation: true, nodeIntegration: false, webSecurity: true } });
  const errors = [];
  window.webContents.on('console-message', (_event, _level, message) => { if (/Refused|Content Security Policy|failed/i.test(message)) errors.push(message); });
  const html = `<!doctype html><html><body><iframe id="frame" sandbox="allow-scripts allow-downloads" src="muster-app://${identity.token}/panel.html"></iframe><script>
  window.addEventListener('message', event => { const frame = document.querySelector('#frame'); if (event.source !== frame.contentWindow || !event.data) return;
    if (event.data.__ma && event.data.type === 'ready') frame.contentWindow.postMessage({ __ma: true, type: 'init', context: { generation: 1, locale: 'en', localeRevision: 1 } }, '*');
    else if (event.data.__ma && event.data.type === 'call') frame.contentWindow.postMessage({ __ma: true, type: 'reply', id: event.data.id, ok: true, result: { content: 'workspace data' } }, '*');
    else if (event.data.localeChange) window.__locale = event.data.localeChange;
    else if (event.data.result) window.__result = event.data.result;
  });</script></body></html>`;
  await window.loadURL(`data:text/html;charset=utf-8,${encodeURIComponent(html)}`);
  const result = await window.webContents.executeJavaScript(`new Promise((resolve, reject) => { const started=Date.now(); const timer=setInterval(() => { if (window.__result) { clearInterval(timer); resolve(window.__result); } else if (Date.now()-started>7000) { clearInterval(timer); reject(new Error('panel SDK handshake timed out')); } }, 20); })`);
  if (result.value !== 'workspace data' || result.color !== 'rgb(1, 2, 3)' || result.locale !== 'en' || errors.length) throw new Error(`Unexpected panel result: ${JSON.stringify({ result, errors })}`);
  const embeddedLocale = await window.webContents.executeJavaScript(`new Promise((resolve, reject) => { const started=Date.now(); document.querySelector('#frame').contentWindow.postMessage({ __ma: true, type: 'appearance', locale: 'zh-CN', localeRevision: 2 }, '*'); const timer=setInterval(() => { if (window.__locale === 'zh-CN') { clearInterval(timer); resolve(window.__locale); } else if (Date.now()-started>7000) { clearInterval(timer); reject(new Error('embedded locale update timed out')); } }, 20); })`);
  if (embeddedLocale !== 'zh-CN') throw new Error('Embedded locale update failed');
  ipcMain.handle('extension:panelInit', () => ({ generation: 1, locale: 'en', localeRevision: 1 }));
  ipcMain.handle('extension:panelCall', () => ({ ok: true, result: { content: 'workspace data' } }));
  const popup = new BrowserWindow({ show: false, webPreferences: { preload: path.join(path.dirname(sdkPath), 'panel-preload.cjs'), sandbox: true, contextIsolation: true, nodeIntegration: false, webSecurity: true } });
  await popup.loadURL(`muster-app://${identity.token}/panel.html`);
  const popupResult = await popup.webContents.executeJavaScript(`new Promise((resolve, reject) => { const started=Date.now(); const timer=setInterval(() => { if (window.__result) { clearInterval(timer); resolve(window.__result); } else if (Date.now()-started>7000) { clearInterval(timer); reject(new Error('standalone SDK handshake timed out')); } }, 20); })`);
  if (popupResult.locale !== 'en' || popupResult.value !== 'workspace data') throw new Error(`Unexpected standalone result: ${JSON.stringify(popupResult)}`);
  popup.webContents.send('extension:appearance', { locale: 'zh-CN', localeRevision: 2 });
  const popupLocale = await popup.webContents.executeJavaScript(`new Promise((resolve, reject) => { const started=Date.now(); const timer=setInterval(() => { if (document.documentElement.lang === 'zh-CN') { clearInterval(timer); resolve(document.documentElement.lang); } else if (Date.now()-started>7000) { clearInterval(timer); reject(new Error('standalone locale update timed out')); } }, 20); })`);
  if (popupLocale !== 'zh-CN') throw new Error('Standalone locale update failed');
  popup.destroy();
  process.stdout.write('extensions-electron-panel: ok\n');
  window.destroy(); app.exit(0);
})().catch(error => { process.stderr.write(String(error.stack || error) + '\n'); app.exit(1); });
